"""Fixed source BuffTile data; independent infection lifetime survives leaving."""
from pathlib import Path
import json,hashlib,sys
from copy import deepcopy
ROOT=Path(__file__).resolve().parents[2]
sys.path.append(str(ROOT))
SOURCE=ROOT/'packages/campaign/chapter08_source_prepare/integration/environment.native.v1.json'
OUT=ROOT/'packages/campaign/chapter08_consumers/environment/infection.module.v3.json'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def build():
 from ark_sim.domains.selection import DEFAULT_STATE,SWITCHES
 src=json.loads(SOURCE.read_bytes());raw=next(c['raw'] for c in src['prefabs']['tile_infection']['components'].values() if c['native_class']=='BuffTile');node=src['bson_templates']['templates']['periodic_damage']['parsed']['eventToActions']['ON_BUFF_TRIGGER'][0]
 assert raw['_clearBuffsWhenLeft']==0 and raw['_buffs'][0]['triggerInterval']==1 and raw['_buffs'][0]['waitFirstTriggerInterval']==1 and node['_attackType']=='BUFF' and node['_damageType']=='PURE' and node['_ignoreForSp'] is True and node['_damageWithoutModify'] is False
 tile=next(t for rows in src['stage_tile_operands'].values() for t in rows if t['tileKey']=='tile_infection');bb={x['key']:x['value'] for x in tile['blackboard']};assert bb=={'damage':180.0,'atk':.5,'attack_speed':50.0,'duration':300.0}
 config={**{k:0 for k in SWITCHES},'_targetSide':7,'_targetMotion':1,'_targetCategory':1,'_ignoreTargetFree':1,'_ignoreAllyTargetFree':1,'_ignoreHealFree':1,'_forceIgnoreCamouflage':1}
 parent='buff/ch8/environment/infection/contact_parent';entry='buff/ch8/environment/infection/model_entry';buff='buff/ch8/environment/tile_infection';entity='unit/ch8/environment/infection_field'
 p={'schemaVersion':2,'manifest':{'id':'package/ch8/environment/infection_v1','requires':['preset/ark_standard'],'metadata':{'source_locks':{str(SOURCE):sha(SOURCE),str(Path(__file__)):sha(Path(__file__)),str(Path(__file__).with_name('policies_v1.py')):sha(Path(__file__).with_name('policies_v1.py'))},'native_BuffTile':raw,'native_periodic_damage':node,'source_blackboard':bb,'reference_policy':{'contact':'Sourceground/category1 allside ignorefree/healfree/currentmodelcell projection. Camo ignore is explicit tilecontact reference choice, not native selector body proof.','lifetime':'NativeclearBuffsWhenLeft0 and refreshRemainingTimeWhenStackMax0: first300s infection persists offcell, existinglive buff neverrefreshes. Modelentry child is only internal contact sentinel, not a fabricated native Buff or combat actor.','damage':'Actor-free sourceNone PURE/BUFF ignoreSPtrue withoutModifyfalse envtrue;180 fixed per1s after30quanta, noactorATK damage path.','stats':'ATK MULTIPLIER.5->directratio+.5;ASPD ADDITION50->normalizedratio flat+.5.','visibility':'Existing source tile/ref routes remain original; explicitprofile only infection.','nativebody_verified':False,'client_verified':False},'tile_profile':{'type':'occupancy_buff_field','definition':entity,'expected_blackboard':bb}}},'entities':[{'id':entity,'kind':'entity','tags':['tile_field_owner'],'components':{'selection_state':{'side':raw['_sourceSide'],'motion':1,'category':2,'unit_type':4},'spatial':{},'buffs':{'initial':[parent]}}}],'selectors':[{'id':'selector/ch8/environment/infection','kind':'selector','region':{'type':'all'},'limit':None,'eligibility':{'rule':'rule/ch8/environment/infection/contact','parameters':{'source_configuration':config,'side_policy':'relative_ally_enemy','neutral_policy':'absolute_mask','defaults':deepcopy(DEFAULT_STATE)}}}],'rules':[{'id':'rule/ch8/environment/infection/contact','kind':'rule','contract':'targeting.eligibility','implementation':{'type':'provider','provider':'reference.c8.infection_contact'}},{'id':'rule/ch8/environment/infection/install','kind':'rule','contract':'buff.application','parameters':{'buff':buff,'duration':bb['duration']},'implementation':{'type':'provider','provider':'reference.c8.infection_once'}}],'buffs':[{'id':parent,'kind':'buff','aura':{'selector':'selector/ch8/environment/infection','buff':entry}},{'id':entry,'kind':'buff','stacking':{'mode':'independent'},'effects':[{'op':'buff_application','allowed':[buff],'application_rule':'rule/ch8/environment/infection/install'}],'metadata':{'model_only_contact_sentinel':True}},{'id':buff,'kind':'buff','duration_seconds':bb['duration'],'interval_seconds':1,'stacking':{'mode':'refresh','identity':['definition','target'],'max_stacks':1},'modifiers':[{'attribute':'atk','layer':'direct_ratio','value':bb['atk']},{'attribute':'attack_speed_ratio','layer':'flat','value':bb['attack_speed']/100}],'effects':[{'op':'no_source_damage','damage_type':'true','attack_type':'BUFF','damage_without_modify':False,'fixed_amount':bb['damage'],'ignore_for_sp':True,'node_is_env_damage':True,'env_blackboard_injected':True,'environmental':True,'origin':{'mechanism':'native_tile_infection_periodic_damage'},'rules':{'damage.pipeline':'rule/ark_damage_pipeline'}}],'metadata':{'nativebuffKey':'tile_infection','native_raw':raw['_buffs'][0]}}]}
 p['rules'].append({'id':'rule/ch8/environment/infection/no_source_pipeline','kind':'rule','contract':'damage.pipeline','implementation':{'type':'expression','expression':"{'accepted':True,'amount':inputs.effect.fixed_amount,'allocations':[],'events':[]}"}})
 p['buffs'][-1]['effects'][0]['rules']['damage.pipeline']='rule/ch8/environment/infection/no_source_pipeline'
 p['rules'][-1]['implementation']={'type':'graph','nodes':[{'id':'settlement','expression':"{'accepted':True,'amount':inputs.effect.fixed_amount,'allocations':[],'events':[]}"}],'output':'nodes.settlement'}
 return p
if __name__=='__main__':
 p=build();OUT.parent.mkdir(parents=True,exist_ok=True)
 with OUT.open('x',encoding='utf8') as f:json.dump(p,f,ensure_ascii=False,indent=2)
 print(sha(OUT))
